"""Helpers for reading and writing small configuration files."""

import json
from pathlib import Path

DEFAULT_NAME = "settings.json"


def read_config(folder, name=DEFAULT_NAME):
    """Return the parsed contents of a configuration file.

    A missing file produces an empty mapping so callers need no special case.
    """
    path = Path(folder) / name
    if not path.exists():
        return {}
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle)


def write_config(folder, values, name=DEFAULT_NAME):
    """Write values to a configuration file, creating folders as needed."""
    path = Path(folder) / name
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        json.dump(values, handle, indent=2, sort_keys=True)


def merge(base, extra):
    """Return a new mapping with the values of extra applied over base."""
    result = dict(base)
    result.update(extra)
    return result


def flatten(mapping, prefix=""):
    """Yield dotted keys and values for nested mappings."""
    for key, value in mapping.items():
        path = prefix + key
        if isinstance(value, dict):
            yield from flatten(value, path + ".")
        else:
            yield path, value


if __name__ == "__main__":
    current = read_config(".")
    print(merge(current, {"version": 2}))
    for key, value in flatten(current):
        print(key, value)

